// RestoredAtIsNil applies the IsNil predicate on the "restored_at" field.
func RestoredAtIsNil() predicate.CounterNotice {
	return predicate.CounterNotice(sql.FieldIsNull(FieldRestoredAt))
}

// RestoredAtNotNil applies the NotNil predicate on the "restored_at" field.
func RestoredAtNotNil() predicate.CounterNotice {
	return predicate.CounterNotice(sql.FieldNotNull(FieldRestoredAt))
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CounterNotice) predicate.CounterNotice {
	return predicate.CounterNotice(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CounterNotice) predicate.CounterNotice {
	return predicate.CounterNotice(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CounterNotice) predicate.CounterNotice {
	return predicate.CounterNotice(sql.NotPredicates(p))
}
